+/// Read a charset declaration from a meta tag in the first 1024 bytes.
+fn sniff_charset(bytes: &[u8]) -> Option<String> {
+    let prefix = String::from_utf8_lossy(&bytes[..bytes.len().min(1024)]).to_ascii_lowercase();
