+        let tag = tag.split('>').next()?;
+        if !tag.trim_start().starts_with("meta") {
+            continue;
+        }
+        if let Some(pos) = tag.find("charset") {
+            let rest = tag[pos + 7..].trim_start();
+            let rest = rest
+                .strip_prefix('=')?
+                .trim_start()
+                .trim_start_matches(['\"', '\'']);
+            let label: String = rest
+                .chars()
+                .take_while(|c| c.is_ascii_alphanumeric() || matches!(c, '-' | '_' | '.'))
+                .collect();
+            if !label.is_empty() {
+                return Some(label);
+            }
+        }
+    }
