        let close_name = rest.as_bytes().get(2).copied().unwrap_or_default();
        if let Some(comment) = rest.strip_prefix("<!--") {
            let length = if comment.starts_with('>') {
                1
            } else if comment.starts_with("->") {
                2
            } else {
                comment.find("-->").map_or(comment.len(), |at| at + 3)
